import{z as o,x as B,o as s,c as d,q as i,j as A,D as r,d as t,s as E,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"ASIC 流程与标准单元","description":"","frontmatter":{"title":"ASIC 流程与标准单元","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/asic-flow-stdcell.md","filePath":"cs/asic-flow-stdcell.md","lastUpdated":1791063341000}'),p={name:"cs/asic-flow-stdcell.md"};function F(S,a,D,C,T,c){const l=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=i('<h1 id="asic-流程与标准单元" tabindex="-1">ASIC 流程与标准单元 <a class="header-anchor" href="#asic-流程与标准单元" aria-label="Permalink to &quot;ASIC 流程与标准单元&quot;">​</a></h1><div class="epigraph"><p>标准单元是预先刻画的门与触发器版图；数字 ASIC 把网表摆到行里再布金属，不再用 LUT 真值表实现布尔函数。</p><footer>—— 据 Weste and Harris, CMOS VLSI Design；Harris and Harris, Digital Design and Computer Architecture；Rabaey, Chandrakasan, Nikolic, Digital Integrated Circuits 整理</footer></div><p><a href="/cs/hls">上一课</a>仍落到 RTL。<a href="/cs/fpga-lut-clb">FPGA LUT</a> 是可配置砖。量产数字芯片走另一条：<strong>标准单元 ASIC</strong>——库里每只 NAND、DFF 有延迟、功耗、版图。缺口是流程角色：综合→DFT→布局→CTS→布线→签核，与 FPGA 开关盒对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准单元行（row）等高，电源轨在行边。布局把 FF 与门放进行，合法化间距。布线在金属层上按设计规则连线，没有预制开关盒，灵活性高、一次性工程费用（NRE）高。缺口不是再讲 LUT 映射，而是：<strong>库</strong>是时序/功耗/噪声模型的来源，STA 用 .lib，版图用 LEF/GDS。</p><p>存储编译器生成 SRAM 宏，对应 FIFO RAM 与 cache，不从标准单元一比特一比特搭（除非很小）。</p><h3 id="标准单元不是「比-fpga-更快的同一架构」" tabindex="-1">标准单元不是「比 FPGA 更快的同一架构」 <a class="header-anchor" href="#标准单元不是「比-fpga-更快的同一架构」" aria-label="Permalink to &quot;标准单元不是「比 FPGA 更快的同一架构」&quot;">​</a></h3><p>同一 RTL 在 ASIC 上通常更快更省电，因为硬连线与可定制时钟树、电压。但架构（流水线深度、FMA 宽度）仍是设计者的，工艺不自动给出华莱士树。把 ASIC 理解成 FPGA 的超频模式，微结构决策会被跳过。</p><p><span class="marginnote">Weste/Harris 与 Rabaey 等 DIC 是 VLSI 教材。Harris DDCA 对比 FPGA/ASIC。本课不进入光刻分辨率、双重图形——那是光刻栏；这里只到「要交给代工厂一套 GDS」。</span></p><p><span class="marginnote">「NRE」（一次性工程费用）就是「为这款芯片定制一套掩膜版要付的一次性钱」，先进工艺流一次片动辄上千万美元，之后每颗成本才便宜——这就是为什么 ASIC 只在量产足够大时才划算，而 FPGA 靠「没有 NRE」吃下小批量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端：RTL、综合、<a href="/cs/sta">STA</a>、形式与仿真。DFT 插入扫描。后端：floorplan、宏放置、标准单元放置、<a href="/cs/clock-skew-cts">CTS</a>、布线、RC 提取、再 STA、物理验证（DRC/LVS）。功耗分析用切换活动。签核角：P-V-T 多角。</p>',12)),(s(),A(n,null,{default:r(()=>[E(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RTL%5B%22RTL%22%5D%20--%3E%20SYN%5B%22%E7%BB%BC%E5%90%88%E5%88%B0%E6%A0%87%E5%87%86%E5%8D%95%E5%85%83%22%5D%0A%20%20SYN%20--%3E%20BE%5B%22%E5%B8%83%E5%B1%80%20CTS%20%E5%B8%83%E7%BA%BF%22%5D%0A%20%20BE%20--%3E%20GDS%5B%22GDS%20%E7%AD%BE%E6%A0%B8%22%5D%0A%20%20GDS%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8A%9F%E8%80%97%E4%BB%8E%E5%93%AA%E6%9D%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"FPGA 比特流可反复下载；ASIC 掩膜一次，验证权重更高——后课验证与 DFT 因此紧挨着功耗之后补全。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"给「可反复」一个数：一块 FPGA 芯片一生可以重新下载数万次，发现 bug 重新编译即可，十分钟后接着测；ASIC 的错误刻在硅片上，改一只门也要重新制版流片，一去就是数月加数百万美元——「验证权重更高」不是口号，是钱。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"功耗墙、时钟门控、老化都作用在这套版图上。软错误针对 SRAM 与 FF。本课先钉「网表有物理身体」。代工 PDK 提供单元与规则；设计者不到晶体管级手画每一个与门。",-1)),a[7]||(a[7]=e("p",null,"同一份 RTL 落到两种「砖」上，差异到底在哪：",-1)),(s(),A(n,null,{default:r(()=>[E(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20RTL%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%20RTL%22%5D%20--%3E%20F%5B%22FPGA%EF%BC%9ALUT%20%E7%9C%9F%E5%80%BC%E8%A1%A8%E5%8A%A0%E5%BC%80%E5%85%B3%E7%9B%92%22%5D%0A%20%20RTL%20--%3E%20A%5B%22ASIC%EF%BC%9A%E6%A0%87%E5%87%86%E5%8D%95%E5%85%83%E7%A1%AC%E8%BF%9E%E7%BA%BF%22%5D%0A%20%20F%20--%3E%20F2%5B%22%E9%9D%A2%E7%A7%AF%E5%A4%A7%E4%B8%80%E4%BA%9B%20%E4%B8%BB%E9%A2%91%E4%BD%8E%E4%B8%80%E4%BA%9B%20NRE%20%E8%BF%91%E9%9B%B6%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E9%9D%A2%E7%A7%AF%E5%B0%8F%20%E6%9B%B4%E5%BF%AB%E6%9B%B4%E7%9C%81%E7%94%B5%20NRE%20%E9%AB%98%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=i('<p><span class="marginnote">常见误区：初学者容易以为「换上先进 ASIC 工艺就自动变快」。工艺只是把砖变好；流水线深度、并行宽度、乘法树形状这些架构决策仍然全在设计者手里，工艺不会自动替你长出华莱士树。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲模拟全定制运放，不写 FinFET 工艺步骤，不把 EUV 光刻机当数字流程的一环。不讨论晶圆经济学细节——摩尔课会从成本侧再进。</p><p>后课默认：数字 ASIC 映射到标准单元行与金属布线；延迟来自 .lib 与提取，不是 LUT 与开关盒。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标准单元是预先刻画的门/FF；ASIC 摆行布金属。</li><li>流程：综合与 DFT 之后物理闭合到 GDS。</li><li>与 FPGA 同 RTL、不同砖与 NRE。</li><li>出处：Weste and Harris；Rabaey et al.；Harris and Harris。</li></ul>',6))])}const m=o(p,[["render",F]]);export{h as __pageData,m as default};
